// Two real freezers. Internal thermostats are set to minimum so the
// outlet is the effective thermostat. Adjust t_max_c / t_target_low_c /
// t_target_high_c per device. The fallback thermal-model numbers are
// used until the learner has enough InfluxDB history.
//
// outlet_kind drives fc_switch_router:
//   tasmota   -> topic=cmd_topic, payload="ON"|"OFF"
//   homematic -> topic=cmd_topic, payload="true"|"false"
const cfg = {
  spike_limit_w: 4000,
  eval_interval_ms: 5 * 60000,
  urgency_horizon_hours_max: 12,
  pv_base_load_w: 400,
  min_cycle_minutes: 10,
  price_hysteresis: 0.02,
  freezers: {
    og_gefrierschrank: {
      temp_topic: 'sensor/status/temperature/og_speis/ht/4',
      pwr_topic: 'tm/tele/OgSpGfr/SENSOR',
      cmd_topic: 'tm/cmnd/OgSpGfr/POWER',
      outlet_kind: 'tasmota',
      t_max_c: -16,
      t_target_high_c: -19,
      t_target_low_c: -23,
      fallback_cooling_rate_c_per_min: -0.25,
      fallback_warming_rate_c_per_min: 0.030,
      fallback_running_power_w: 120
    },
    kg_kuehltruhe: {
      temp_topic: 'sensor/status/temperature/kg_garage/ht/1',
      pwr_topic: null,
      influx_power_tag: 'NEQ1809653',
      cmd_topic: 'hm/set/HM-ES-PMSw1-Pl NEQ1809653:1/STATE',
      outlet_kind: 'homematic',
      t_max_c: -16,
      t_target_high_c: -19,
      t_target_low_c: -22,
      fallback_cooling_rate_c_per_min: -0.20,
      fallback_warming_rate_c_per_min: 0.025,
      fallback_running_power_w: 100
    }
  }
};
flow.set('config', cfg);

const freezers = global.get('freezers') || {};
for (const name of Object.keys(cfg.freezers)) {
  if (!freezers[name]) {
    freezers[name] = {
      name: name,
      state: 'idle',
      reason: 'init',
      override: 'AUTO',
      current_temp_c: null,
      current_power_w: null,
      last_temp_update: null,
      last_power_update: null,
      last_state_change_at: Date.now(),
      last_decision_at: null,
      model: {
        cooling_rate_c_per_min: cfg.freezers[name].fallback_cooling_rate_c_per_min,
        warming_rate_c_per_min: cfg.freezers[name].fallback_warming_rate_c_per_min,
        running_power_w: cfg.freezers[name].fallback_running_power_w,
        samples: 0,
        last_refresh: null
      }
    };
  }
}
// Prune stale placeholder devices no longer in cfg.
for (const k of Object.keys(freezers)) {
  if (!cfg.freezers[k]) delete freezers[k];
}
global.set('freezers', freezers);

if (flow.get('price_now') == null) flow.set('price_now', 0.30);
if (!flow.get('price_forecast')) flow.set('price_forecast', []);
if (!flow.get('pv_forecast_by_hour')) flow.set('pv_forecast_by_hour', new Array(24).fill(0));
return null;

// Sensor payload for both freezers is {value: <degC>, id, name, tst}.
const cfg = flow.get('config') || {};
const fs = cfg.freezers || {};
let device = null;
for (const name of Object.keys(fs)) {
  if (fs[name].temp_topic === msg.topic) { device = name; break; }
}
if (!device) return null;
const p = msg.payload;
if (!p || typeof p !== 'object' || p.value == null) return null;
const t = Number(p.value);
if (isNaN(t)) return null;
const norm = { topic: 'home/freezer/' + device + '/temperature', payload: t, device_name: device };
const influx = {
  topic: 'freezer',
  payload: [{ device: device }, { temperature: t }]
};
return [norm, influx];

const cfg = flow.get('config') || {};
const fs = cfg.freezers || {};
let device = null;
for (const name of Object.keys(fs)) {
  if (fs[name].pwr_topic === msg.topic) { device = name; break; }
}
if (!device) return null;
const p = msg.payload;
if (!p || !p.ENERGY || p.ENERGY.Power == null) return null;
const w = Number(p.ENERGY.Power);
if (isNaN(w)) return null;
const norm = { topic: 'home/freezer/' + device + '/power', payload: w, device_name: device };
const influx = {
  topic: 'freezer',
  payload: [{ device: device }, { power: w }]
};
return [norm, influx];

// Merges the latest temperature or power reading into global.freezers[<name>]
// and re-evaluates the decision for that device. Runs synchronously so the
// outlet reacts to the temperature tick that pushed it over the ceiling.
const name = msg.device_name;
if (!name) return null;
const topic = msg.topic || '';
const freezers = global.get('freezers') || {};
const dev = freezers[name];
if (!dev) return null;
const now = Date.now();
if (topic.endsWith('/temperature')) {
  dev.current_temp_c = Number(msg.payload);
  dev.last_temp_update = now;
} else if (topic.endsWith('/power')) {
  dev.current_power_w = Number(msg.payload);
  dev.last_power_update = now;
}
freezers[name] = dev;
global.set('freezers', freezers);
return { device_name: name, payload: dev, trigger: 'state_update' };

// Emit one InfluxDB query per freezer that has influx_power_tag and no
// direct MQTT power source. Reads measurement 'power' in database tmp
// (configured on the influxdb_config node), field val, tag device.
const cfg = flow.get('config') || {};
const fs = cfg.freezers || {};
const out = [];
for (const name of Object.keys(fs)) {
  const f = fs[name];
  if (!f.influx_power_tag || f.pwr_topic) continue;
  out.push({
    device_name: name,
    query: "SELECT last(val) AS val FROM power WHERE device = '" + f.influx_power_tag + "' AND time > now() - 5m"
  });
}
return [out];

const name = msg.device_name;
if (!name) return null;
const rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!rows.length || rows[0].val == null) return null;
const w = Number(rows[0].val);
if (isNaN(w)) return null;
return { topic: 'home/freezer/' + name + '/power', payload: w, device_name: name };

const cfg = flow.get('config') || {};
const fs = cfg.freezers || {};
const out = [];
for (const name of Object.keys(fs)) {
  out.push({ device_name: name, trigger: 'tick' });
}
return [out];

function localIso(ms){const d=new Date(ms);const pad=n=>String(n).padStart(2,'0');const off=-d.getTimezoneOffset();const sign=off>=0?'+':'-';const oh=pad(Math.floor(Math.abs(off)/60));const om=pad(Math.abs(off)%60);return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())+'T'+pad(d.getHours())+':'+pad(d.getMinutes())+':'+pad(d.getSeconds())+sign+oh+':'+om;}
const SLOT_MS = 15 * 60000;
const SLOT_H = 0.25;

const isTest = !!msg._test;
const t = isTest ? msg._test : null;
const name = isTest ? t.device_name : msg.device_name;
if (!name) return null;

const cfg = isTest ? t.cfg : (flow.get('config') || {});
const fcfg = (cfg.freezers || {})[name];
if (!fcfg) return null;

const freezers = isTest ? (t.freezers || {}) : (global.get('freezers') || {});
const dev = freezers[name];
if (!dev) return null;

const now = isTest && t.now != null ? t.now : Date.now();
const price_now = isTest ? (t.price_now != null ? t.price_now : 0.30) : (flow.get('price_now') || 0.30);
const forecastSrc = isTest ? (t.price_forecast || []) : (flow.get('price_forecast') || []);
const forecast = forecastSrc
  .map(s => ({ t: new Date(s.time).getTime(), p: Number(s.price) }))
  .filter(s => !isNaN(s.t) && !isNaN(s.p))
  .sort((a, b) => a.t - b.t);
const pv_now = Math.max(0, Number(isTest ? t.ess_pac : ((global.get('ess') || {}).pac)) || 0);
const pv_curve = isTest ? (t.pv_curve || new Array(24).fill(0)) : (flow.get('pv_forecast_by_hour') || new Array(24).fill(0));
const pv_base_load_w = cfg.pv_base_load_w || 0;

const T = dev.current_temp_c;
const T_max = fcfg.t_max_c;
const T_hi = fcfg.t_target_high_c;
const T_lo = fcfg.t_target_low_c;
const wasOn = (dev.state === 'cooling' || dev.state === 'safety');
const model = dev.model || {};
const cooling = Number(model.cooling_rate_c_per_min) || fcfg.fallback_cooling_rate_c_per_min || -0.25;
const warming = Math.max(0.005, Number(model.warming_rate_c_per_min) || fcfg.fallback_warming_rate_c_per_min || 0.03);
const load = Number(model.running_power_w) || fcfg.fallback_running_power_w || 120;

// Scheduling variables used by the OFF branch. Declared up here so the
// diagnostic closure in buildResult can read them for any early return.
let hoursToMax = 0;
let coolingMinutes = 0;
let slotCount = 1;
let candidates = [];
let best = null;
let evalNow = { cost: 0, firstNet: 0, firstPv: 0 };

// Respect explicit user override first.
if (dev.override === 'ON')  return buildResult(true,  'override_on');
if (dev.override === 'OFF') return buildResult(false, 'override_off');

// No temperature yet - cautious: keep current state, no switch change.
if (T == null || isNaN(T)) return buildResult(wasOn, 'no_reading');

// Hard safety ceiling.
if (T >= T_max) return buildResult(true, 'safety_ceiling');

// Low-target floor: once deeply cold, stop.
if (wasOn && T <= T_lo) return buildResult(false, 'low_target_reached');

// Continue an in-progress cooling cycle until we hit the low target.
if (wasOn && T > T_lo) return buildResult(true, 'cycle_continue');

// OFF branch: schedule the next cooling cycle.
hoursToMax = Math.max(0, (T_max - T) / warming / 60);
const horizonH = Math.min(hoursToMax, cfg.urgency_horizon_hours_max || 12);
const horizonMs = horizonH * 3600000;
coolingMinutes = Math.max(1, Math.abs((T - T_lo) / cooling));
slotCount = Math.max(1, Math.ceil(coolingMinutes / 15));

function pvAt(tt) {
  if (Math.abs(tt - now) < 10 * 60000) return pv_now;
  const h = new Date(tt).getHours();
  return pv_curve[h] || 0;
}
function priceAt(tt) {
  if (tt < now + SLOT_MS) return price_now;
  let p = price_now;
  for (const s of forecast) {
    if (s.t <= tt) p = s.p; else break;
  }
  return p;
}
function netGridAt(tt) {
  const pv_surplus = Math.max(0, pvAt(tt) - pv_base_load_w);
  return Math.max(0, load - pv_surplus);
}
function evaluate(startT) {
  let cost = 0, firstNet = 0, firstPv = 0;
  for (let i = 0; i < slotCount; i++) {
    const tt = startT + i * SLOT_MS;
    const ng = netGridAt(tt);
    cost += (ng * SLOT_H / 1000) * priceAt(tt);
    if (i === 0) { firstNet = ng; firstPv = pvAt(tt); }
  }
  return { cost: cost, firstNet: firstNet, firstPv: firstPv };
}
function alignSlot(tt) { return Math.floor(tt / SLOT_MS) * SLOT_MS; }

candidates = [now];
let tGrid = alignSlot(now) + SLOT_MS;
const latestStart = now + Math.max(0, horizonMs - coolingMinutes * 60000);
while (tGrid <= latestStart) { candidates.push(tGrid); tGrid += SLOT_MS; }

for (const startT of candidates) {
  const ev = evaluate(startT);
  if (!best || ev.cost + 1e-9 < best.cost) best = { time: startT, cost: ev.cost, firstNet: ev.firstNet, firstPv: ev.firstPv };
}

const mustCoolNow = T >= T_hi && hoursToMax < (coolingMinutes / 60);
const pvCoversNow = pvAt(now) - pv_base_load_w >= load;
evalNow = evaluate(now);
const priceHyst = cfg.price_hysteresis || 0;

let on, reason;
if (mustCoolNow) { on = true; reason = 'urgency'; }
else if (pvCoversNow) { on = true; reason = 'pv_cover_now'; }
else if (best && best.time <= now + 60000 && best.cost + priceHyst >= evalNow.cost && T >= T_hi) {
  on = true; reason = 'cheapest_now';
}
else if (best && best.time > now + 60000) { on = false; reason = 'defer_to_cheaper'; }
else if (T < T_hi) { on = false; reason = 'hold_below_high'; }
else { on = false; reason = 'hold'; }

return buildResult(on, reason);

function buildResult(wantOn, reason) {
  const command = wantOn ? 'ON' : 'OFF';
  const newState = wantOn ? (T != null && T >= T_max ? 'safety' : 'cooling') : 'idle';
  const changed = newState !== dev.state;
  const minCycleMs = (cfg.min_cycle_minutes || 0) * 60000;
  const sinceChange = now - (dev.last_state_change_at || 0);
  // Respect min cycle time to avoid rapid toggling (safety ceiling overrides).
  const gated = changed && reason !== 'safety_ceiling' && reason !== 'override_on' && reason !== 'override_off' && sinceChange < minCycleMs;
  if (isTest) {
    const expected = t.expected || null;
    let pass = null;
    if (expected) {
      pass = true;
      if (expected.command && expected.command !== command) pass = false;
      if (expected.reason && expected.reason !== reason) pass = false;
      if (expected.state && expected.state !== newState) pass = false;
    }
    return [null, null, {
      topic: 'test/' + (t.label || name),
      payload: {
        label: t.label || null,
        pass: pass,
        expected: expected,
        got: { command: command, reason: reason, state: newState, gated: gated },
        diagnostics: {
          now: localIso(now),
          temp_c: T,
          t_max: T_max, t_high: T_hi, t_low: T_lo,
          pv_now_w: Math.round(pv_now),
          price_now: price_now,
          cooling_rate: cooling,
          warming_rate: warming,
          running_power_w: load,
          hours_to_max: Math.round(hoursToMax * 100) / 100,
          cooling_minutes: Math.round(coolingMinutes * 10) / 10,
          slot_count: slotCount,
          candidates_evaluated: candidates.length,
          best_time: best ? localIso(best.time) : null,
          best_cost_eur: best ? Math.round(best.cost * 1000) / 1000 : null,
          now_cost_eur: Math.round(evalNow.cost * 1000) / 1000
        }
      }
    }];
  }
  if (gated) {
    // Leave command unsent; still publish status for visibility.
    const statusMsg = {
      topic: 'home/freezer/' + name + '/status',
      payload: JSON.stringify({
        state: dev.state, reason: 'gated_min_cycle', device: name,
        temp_c: T, target_command: command, intended_reason: reason,
        temp_max_c: T_max, price_now: price_now,
        pv_now_w: Math.round(pv_now),
        updated_at: localIso(now)
      }),
      retain: true
    };
    dev.last_decision_at = now;
    freezers[name] = dev;
    global.set('freezers', freezers);
    return [null, statusMsg, null];
  }
  if (changed) {
    dev.state = newState;
    dev.last_state_change_at = now;
  }
  dev.reason = reason;
  dev.last_decision_at = now;
  freezers[name] = dev;
  global.set('freezers', freezers);
  const switchMsg = changed ? { topic: 'home/freezer/' + name + '/set', payload: command } : null;
  const statusMsg = {
    topic: 'home/freezer/' + name + '/status',
    payload: JSON.stringify({
      state: newState, reason: reason, device: name,
      temp_c: T, temp_max_c: T_max,
      current_power_w: dev.current_power_w,
      price_now: price_now,
      pv_now_w: Math.round(pv_now),
      updated_at: localIso(now),
      model: dev.model
    }),
    retain: true
  };
  return [switchMsg, statusMsg, null];
}

// Translate home/freezer/<name>/set ON|OFF into the device's native command
// topic + payload. Tasmota wants literal ON/OFF, Homematic wants true/false.
const parts = (msg.topic || '').split('/');
if (parts.length < 4 || parts[0] !== 'home' || parts[1] !== 'freezer') return null;
const name = parts[2];
const action = String(msg.payload).toUpperCase();
if (action !== 'ON' && action !== 'OFF') return null;
const cfg = flow.get('config') || {};
const fcfg = (cfg.freezers || {})[name];
if (!fcfg) { node.warn('switch router: unknown freezer ' + name); return null; }
let payload;
switch (fcfg.outlet_kind) {
  case 'tasmota':   payload = action; break;
  case 'homematic': payload = action === 'ON' ? 'true' : 'false'; break;
  default: node.warn('switch router: unknown outlet_kind ' + fcfg.outlet_kind + ' for ' + name); return null;
}
return { topic: fcfg.cmd_topic, payload: payload, _device: name, _kind: fcfg.outlet_kind };

const parts = (msg.topic || '').split('/');
const name = parts[2];
const v = String(msg.payload || '').toUpperCase();
if (!name) return null;
if (v !== 'ON' && v !== 'OFF' && v !== 'AUTO') { node.warn('override: bad value ' + v); return null; }
const freezers = global.get('freezers') || {};
const dev = freezers[name];
if (!dev) { node.warn('override: unknown freezer ' + name); return null; }
dev.override = v;
freezers[name] = dev;
global.set('freezers', freezers);
return { device_name: name, trigger: 'override' };

const cfg = flow.get('config') || {};
const fs = cfg.freezers || {};
const out = [];
for (const name of Object.keys(fs)) {
  out.push({
    device_name: name,
    query: "SELECT mean(temperature) AS temp, mean(power) AS pwr FROM freezer WHERE device = '" + name + "' AND time > now() - 7d GROUP BY time(5m) fill(previous)"
  });
}
return [out];

// Produces per-device cooling_rate, warming_rate and running_power from the
// last 7 days of 5-min buckets. A bucket is classified as 'on' when mean
// power > 30W, 'off' when < 5W; anything between is ignored as transitional.
// dT/dt between consecutive buckets of the same class is the sample.
const name = msg.device_name;
if (!name) return null;
const rows = Array.isArray(msg.payload) ? msg.payload : [];
if (rows.length < 2) return null;
const ONW = 30, OFFW = 5;
const coolingSamples = [], warmingSamples = [], runningPowers = [];
for (let i = 1; i < rows.length; i++) {
  const a = rows[i - 1], b = rows[i];
  if (!a || !b) continue;
  const ta = a.time ? new Date(a.time).getTime() : null;
  const tb = b.time ? new Date(b.time).getTime() : null;
  if (!ta || !tb || tb <= ta) continue;
  const Ta = Number(a.temp), Tb = Number(b.temp);
  const Pa = Number(a.pwr),  Pb = Number(b.pwr);
  if (isNaN(Ta) || isNaN(Tb) || isNaN(Pa) || isNaN(Pb)) continue;
  const dtMin = (tb - ta) / 60000;
  if (dtMin < 1 || dtMin > 60) continue;
  const dT = (Tb - Ta) / dtMin;
  const avgP = (Pa + Pb) / 2;
  if (Pa > ONW && Pb > ONW) {
    coolingSamples.push(dT);
    runningPowers.push(avgP);
  } else if (Pa < OFFW && Pb < OFFW) {
    warmingSamples.push(dT);
  }
}
function mean(a) { return a.length ? a.reduce((s, x) => s + x, 0) / a.length : null; }
const cooling = mean(coolingSamples);
const warming = mean(warmingSamples);
const runPwr = mean(runningPowers);
const freezers = global.get('freezers') || {};
const dev = freezers[name];
if (!dev) return null;
const model = dev.model || {};
if (cooling != null && cooling < -0.01) model.cooling_rate_c_per_min = Math.round(cooling * 1000) / 1000;
if (warming != null && warming > 0.002) model.warming_rate_c_per_min = Math.round(warming * 1000) / 1000;
if (runPwr != null && runPwr > 20)     model.running_power_w = Math.round(runPwr);
model.samples = coolingSamples.length + warmingSamples.length;
model.last_refresh = Date.now();
dev.model = model;
freezers[name] = dev;
global.set('freezers', freezers);
return { topic: 'freezer_model/' + name, payload: { device: name, model: model, cooling_samples: coolingSamples.length, warming_samples: warmingSamples.length } };

const v = Number(msg.payload);
if (!isNaN(v)) flow.set('price_now', v);
return null;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const buckets = new Array(24).fill(null).map(() => []);
for (const r of rows) {
  const t = r.time ? new Date(r.time).getTime() : null;
  let v = null;
  if (r.mean != null) v = Number(r.mean);
  else if (r.mean_PAC != null) v = Number(r.mean_PAC);
  if (t == null || v == null || isNaN(v)) continue;
  const h = new Date(t).getHours();
  buckets[h].push(v);
}
const curve = buckets.map(b => b.length ? Math.round(b.reduce((a,c) => a + c, 0) / b.length) : 0);
flow.set('pv_forecast_by_hour', curve);
return null;

const now = new Date('2026-04-21T03:00:00+02:00').getTime();
msg._test = {
  label: 'T1: over max -> safety',
  device_name: 'freezer_kitchen',
  now: now,
  cfg: { pv_base_load_w: 400, urgency_horizon_hours_max: 12, min_cycle_minutes: 0, freezers: { freezer_kitchen: { t_max_c: -15, t_target_high_c: -18, t_target_low_c: -22, fallback_cooling_rate_c_per_min: -0.3, fallback_warming_rate_c_per_min: 0.03, fallback_running_power_w: 120 } } },
  freezers: { freezer_kitchen: { name: 'freezer_kitchen', state: 'idle', override: 'AUTO', current_temp_c: -14.5, last_state_change_at: now - 3600000, model: {} } },
  price_now: 0.30, price_forecast: [], pv_curve: new Array(24).fill(0), ess_pac: 0,
  expected: { command: 'ON', reason: 'safety_ceiling', state: 'safety' }
};
msg.device_name = msg._test.device_name;
return msg;

const now = new Date('2026-04-21T03:00:00+02:00').getTime();
msg._test = {
  label: 'T2: low floor -> OFF',
  device_name: 'freezer_kitchen',
  now: now,
  cfg: { pv_base_load_w: 400, urgency_horizon_hours_max: 12, min_cycle_minutes: 0, freezers: { freezer_kitchen: { t_max_c: -15, t_target_high_c: -18, t_target_low_c: -22, fallback_cooling_rate_c_per_min: -0.3, fallback_warming_rate_c_per_min: 0.03, fallback_running_power_w: 120 } } },
  freezers: { freezer_kitchen: { name: 'freezer_kitchen', state: 'cooling', override: 'AUTO', current_temp_c: -22.5, last_state_change_at: now - 3600000, model: {} } },
  price_now: 0.30, price_forecast: [], pv_curve: new Array(24).fill(0), ess_pac: 0,
  expected: { command: 'OFF', reason: 'low_target_reached', state: 'idle' }
};
msg.device_name = msg._test.device_name;
return msg;

const now = new Date('2026-04-21T13:00:00+02:00').getTime();
msg._test = {
  label: 'T3: mid-band, PV covers -> ON',
  device_name: 'freezer_kitchen',
  now: now,
